/* ----------------------------------------------------------------------- */

filetype_t filetype_from_riscos(unsigned short riscos)
{
  int i;

  /* g_filetypes is generated in ascending order of number */
  i = bsearch_ushort(&g_filetypes[0].riscos, NELEMS(g_filetypes),
                     sizeof(g_filetypes[0]), riscos);
  if (i >= 0)
    return g_filetypes[i];

  return (filetype_t) { riscos, filetype_DATA.ext, "" };
}

filetype_t filetype_from_ext(const char *ext)
{
  size_t i;

  if (ext == NULL)
    return filetype_DATA;

  for (i = 0; i < NELEMS(g_extensions); i++)
    if (strcasecmp(g_extensions[i].ext, ext) == 0)
      return filetype_from_riscos(g_extensions[i].riscos);

  return filetype_DATA;
}

result_t filetype_set(const char *path, filetype_t type)
{
  if (path == NULL)
    return result_NULL_ARG;

#ifdef __riscos

  {
    _kernel_oserror *err;

    /* OS_File 18: set a file's type. */
    err = _swix(OS_File, _INR(0,2), 18, path, type.riscos);
    if (err != NULL)
      return result_FILE_NOT_FOUND;
  }

#else

  NOT_USED(type);

#endif

  return result_OK;
}
